    getFileExt: function getFileExt(name) {
      var extension = name.split(".");
      extension = extension[extension.length - 1];
      return extension.toLowerCase();
    },
    getFileIcon: function getFileIcon(note) {
      if (note.preview) {
        //                    return 'data:' + note.mime + ';base64,' + note.preview;
        return note.preview;
      }

      var name = note.original_document_name;

      var exists_icons = ["7z", "rar", "zip", "word", "excel", "pdf", "image"];
      var extension = this.getFileExt(name);
      switch (extension) {
        case "doc":
        case "docx":
          extension = "word";
          break;
        case "xls":
        case "xlsx":
          extension = "excel";
          break;
        case "png":
        case "jpg":
        case "jpeg":
        case "gif":
          extension = "image";
          break;
      }
      if (exists_icons.indexOf(extension) !== -1) {
        this.default_document_previews[note.aws_document_name] = "/images/file_type/" + extension + ".png";
      } else {
        this.default_document_previews[note.aws_document_name] = "/images/file_type/default.png";
      }
    },
